import{_ as s,Y as t,o as a,c as o,aq as n,H as r}from"./chunks/framework.DbprFcE_.js";import"./chunks/theme.BMQi1xG-.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/home.md","filePath":"en/guide/home.md"}'),p={name:"en/guide/home.md"};function l(d,i,h,c,g,k){const e=t("NolebaseGitChangelog");return a(),o("div",null,[i[0]||(i[0]=n(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><blockquote><p><code>Gropify</code> is a type-safe and modern properties plugin for Gradle.</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>This plugin is designed for Gradle build scripts. It aims to bring properties similar to those in the <code>gradle.properties</code> file into build scripts in a type-safe way, avoiding problems that hard-coded strings might cause.</p><p>The project icon was designed by <a href="https://github.com/Lagrio" target="_blank" rel="noreferrer">MaiTungTM</a>. The name comes from <strong>G</strong>radleP<strong>ropify</strong>, meaning a plugin for Gradle properties.</p><p>It is a brand-new project rebuilt from <a href="https://github.com/HighCapable/SweetProperty" target="_blank" rel="noreferrer">SweetProperty</a>, borrowing previous design ideas and making it more polished and easier to use.</p><p>The configuration plan format of Gropify is similar to SweetProperty. If you are using SweetProperty, you can consider migrating to Gropify.</p><h2 id="alternatives-comparison" tabindex="-1">Alternatives Comparison <a class="header-anchor" href="#alternatives-comparison" aria-label="Permalink to &quot;Alternatives Comparison&quot;">​</a></h2><p>This isn&#39;t just another ordinary <code>BuildConfig</code> plugin. Here is how Gropify stacks up against existing solutions in the community:</p><table tabindex="0"><thead><tr><th>Feature Dimension</th><th>Official Approach</th><th>Traditional Plugins</th><th>Alternatives</th><th>Gropify</th></tr></thead><tbody><tr><td><strong>Buildscript Access</strong></td><td>❌ Hard-coded strings like <code>providers.gradleProperty(&quot;foo.bar&quot;)</code></td><td>❌ Unsupported, requires manual <code>.kts</code> binding</td><td>-</td><td><strong>✅ Auto-generated chainable accessors</strong> <code>gropify.foo.bar</code> (with IDE autocompletion)</td></tr><tr><td><strong>Source Code Constants</strong></td><td>❌ Only Android supports <code>buildConfigField</code>, lacking native KMP/JVM support</td><td>✅ Supports multi-platform constants, but needs explicit <code>.kts</code> declarations</td><td><a href="https://github.com/gmazzo/gradle-buildconfig-plugin" target="_blank" rel="noreferrer">gmazzo/gradle-buildconfig-plugin</a></td><td><strong>✅ Zero manual declarations</strong>, infers and mounts directly from properties</td></tr><tr><td><strong>KMP Multiplatform</strong></td><td>❌ No native mapping</td><td>✅ Supports expect/actual generation</td><td><a href="https://github.com/yshrsmz/BuildKonfig" target="_blank" rel="noreferrer">yshrsmz/BuildKonfig</a></td><td><strong>✅ Flawlessly integrated</strong>, automatically mounted to the <code>commonMain</code> source set</td></tr><tr><td><strong>Configuration Redundancy</strong></td><td><strong>❌ High</strong> (Keys scattered as strings across files)</td><td><strong>⚠️ Medium</strong> (Requires boilerplate mappings in <code>.kts</code>)</td><td>-</td><td><strong>✅ Ultra-low</strong> (Properties act as the Schema)</td></tr><tr><td><strong>Design Philosophy</strong></td><td>Fragmented capabilities</td><td>CodeGen-First (Code generation tooling)</td><td>-</td><td>Properties-Centric (Single source of truth)</td></tr></tbody></table><h2 id="features-overview" tabindex="-1">Features Overview <a class="header-anchor" href="#features-overview" aria-label="Permalink to &quot;Features Overview&quot;">​</a></h2><p>Gropify is mainly designed for Kotlin DSL build scripts. Groovy can directly use properties from the <code>gradle.properties</code> file as variables, but you can still use Gropify to achieve type-safe property access.</p><p>Gropify also supports generating properties (similar to those defined in a <code>gradle.properties</code> file) in a type-safe way into the source code of Kotlin, Java, and Android projects for use at application runtime—similar to Android&#39;s <code>BuildConfig</code>&#39;s <code>buildConfigField</code> feature.</p><p>Suppose we have the following <code>gradle.properties</code> file.</p><blockquote><p>The following example</p></blockquote><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project.app.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Gropify-Demo</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project.app.version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1.0.0</span></span></code></pre></div><p>Here is an example of calling the code automatically generated by Gropify.</p><blockquote><p>Build Script (Kotlin DSL, Groovy DSL)</p></blockquote><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify.project.app.name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify.project.app.version</span></span></code></pre></div><div class="language-groovy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">groovy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span></code></pre></div><blockquote><p>Source Code (Kotlin, Java)</p></blockquote><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_NAME</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_VERSION</span></span></code></pre></div><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_NAME;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_VERSION;</span></span></code></pre></div><p>Gropify also supports Kotlin Multiplatform projects, and you can use the generated property classes in the <code>commonMain</code> source set.</p><h2 id="language-requirement" tabindex="-1">Language Requirement <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;Language Requirement&quot;">​</a></h2><p>It&#39;s recommended to use Kotlin DSL to configure your project&#39;s build scripts. Groovy is also supported, but in pure Groovy projects some configuration syntax may have compatibility issues.</p><p>In Groovy DSL, we will no longer be responsible for troubleshooting and fixing any issues that arise from using this plugin, and it may be completely unsupported in future versions.</p><h2 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h2><p>The maintenance of this project is inseparable from the support and contributions of all developers.</p><p>This project is currently in its early stages, and there may still be some problems or lack of functions you need.</p><p>If possible, feel free to submit a PR to contribute features you think are needed to this project or go to <a href="https://github.com/HighCapable/Gropify/issues" target="_blank" rel="noreferrer">GitHub Issues</a> to make suggestions to us.</p>`,31)),r(e)])}const b=s(p,[["render",l]]);export{m as __pageData,b as default};
